    public static CardEntry[] For(Character c) => c switch
    {
        Character.Ironclad => Ironclad,
        Character.Silent => Silent,
        Character.Defect => Defect,
        Character.Regent => Regent,
        Character.Necrobinder => Necrobinder,
        _ => Ironclad,
    };
